examples.code:
# Uso de continue para saltar el numero 2
print("Prueba continue:")
for n in range(1, 4):
    if n == 2:
        continue
    print(n)

# Uso de break para detenerse en el numero 2
print("Prueba break:")
for n in range(1, 4):
    if n == 2:
        break
    print(n)

